package cn.zhuatech.sqlagent.controller; import cn.zhuatech.sqlagent.common.ApiResponse; import cn.zhuatech.sqlagent.dto.SqlAgentDto.*; import cn.zhuatech.sqlagent.service.SqlAgentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final SqlAgentService service;public OperationsAdminController(SqlAgentService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
